  "slice": {
    "outcome": "An authorized account reviewer can open Account Review in a model-driven app and see no more than ten active synthetic accounts, newest by createdon first, with only name and accountnumber displayed.",
    "entry": "The account reviewer selects Account Review from model-driven app navigation. The HTML web resource starts in an accessible loading state and initiates one read through its account-review data module.",
    "validation": "The data module uses the immutable validated query contract, accepts only a Dataverse entities array, limits rendering to the returned maximum of ten rows, treats missing optional field values safely, preserves service ordering, rejects malformed responses, and ignores an older response after a newer refresh. Dataverse privileges remain authoritative; no local permission bypass or client-side schema inference is allowed.",
    "persistence_or_action": "The account-review data module is the single owner of the read action and calls Xrm.WebApi.retrieveMultipleRecords(\"account\", \"?$select=name,accountnumber&$filter=statecode eq 0&$orderby=createdon desc&$top=10\"). The operation is read-only and naturally repeatable. A monotonic request identifier prevents duplicate rendering and stale-response overwrite; no Dataverse record is created or changed.",
    "feedback": "Show an announced loading state, a two-column success grid, a clear empty state when no active accounts exist, a permission-safe access message for authorization failure, and a retryable message for transient failure. Disable repeated refresh while a request is active, retain keyboard focus predictably, truncate or wrap long content without losing accessible names, and provide a usable narrow-screen layout.",
    "telemetry": "Emit an approved organisational account_review_load event with a privacy-safe correlation ID, outcome category, duration, returned row count, retry indicator, and stale-response indicator. Exclude account names, account numbers, record identifiers, query response bodies, environment URLs, user identifiers, credentials, and error payloads.",
    "evidence": "Current proof is limited to externally preserved, schema-valid specialist query evidence. Implementation must separately produce source/static validation, automated UI and data-module tests, solution package and dependency integrity evidence, authorized deployment/configuration readback, and target runtime evidence for success, empty, permission, failure, retry, accessibility, and out-of-order response behavior.",
    "scope": [
      "One Account Review navigation entry in the target model-driven app",
      "One Xrm.WebApi-backed read-only account review surface",
      "Exact validated selection of name and accountnumber",
      "Active filtering with statecode equal to zero",
      "Descending createdon ordering and top-ten limiting",
      "Loading, success, empty, permission, transient-error, retry, narrow-layout, and stale-response states",
      "Privacy-safe telemetry and correlation",
      "Focused automated tests, ALM packaging, deployment checks, and rollback definition"
    ],
    "exclusions": [
      "Authentication, tenant inspection, live metadata discovery, deployment, or environment administration in this invocation",
      "Account creation, update, deletion, acknowledgement, or other record writes",
      "Custom tables, custom Account columns, connectors, flows, plugins, or AI components",
      "Native saved-view or FetchXML construction",
      "Paging beyond the first ten records",
      "Export, bulk actions, inline editing, search, filtering controls, or drill-down account forms",
      "Transfer of organisational account data or telemetry payloads into the personal OpenAI zone"
    ]
  },
  "architecture": {
    "experience": [
      {
        "id": "EXP-001",
        "decision": "Expose a read-only Account Review HTML web resource through the model-driven app navigation.",
        "rationale": "This is the smallest client surface that directly honors the required Xrm.WebApi contract while supporting complete feedback and accessibility states.",
        "evidence_status": "Assumption"
      },
      {
        "id": "EXP-002",
        "decision": "Render an accessible two-column grid for name and accountnumber with explicit loading, empty, permission, error, and retry states.",
        "rationale": "The visible experience matches the requested review journey and avoids a placeholder-only implementation.",
        "evidence_status": "Confirmed"
      }
    ],
    "data": [
      {
        "id": "DAT-001",
        "decision": "Read the standard synthetic account table using only name and accountnumber in the result projection, statecode=0 for active filtering, and createdon descending for ordering.",
        "rationale": "These schema facts and numeric state mapping are resolved by the validated specialist result.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "DAT-002",
        "decision": "Perform no durable write and retain no account result data in browser storage or telemetry.",
        "rationale": "The slice is read-only and data minimization reduces privacy, stale-data, and rollback risk.",
        "evidence_status": "Confirmed"
      }
    ],
    "integration": [
      {
        "id": "INT-001",
        "decision": "Use only the model-driven client Xrm.WebApi boundary; add no connector, flow, webhook, custom API, or direct authenticated HTTP caller.",
        "rationale": "The approved query is already expressed for the required host, and an additional integration owner would add no slice value.",
        "evidence_status": "Confirmed"
      }
    ],
    "ai": [
      {
        "id": "AI-001",
        "decision": "Use no AI, Copilot, prompt, model, or generative component in this slice.",
        "rationale": "The requested outcome is deterministic account retrieval and display.",
        "evidence_status": "Confirmed"
      }
    ],
    "security": [
      {
        "id": "SEC-001",
        "decision": "Execute Xrm.WebApi under the signed-in organizational user's existing Dataverse privileges and add no embedded credential or privilege elevation path.",
        "rationale": "Authorization remains with Dataverse and the model-driven app security model.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "SEC-002",
        "decision": "Keep target account data inside the organisational Microsoft zone and emit only approved, payload-free telemetry.",
        "rationale": "Only synthetic delegation evidence is permitted in the personal OpenAI zone; runtime organizational data must not cross that boundary.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "SEC-003",
        "decision": "Resolve reviewer role mapping and any field-level access requirements before deployment.",
        "rationale": "Role names and target configuration are environment-specific implementation values and were not supplied.",
        "evidence_status": "Assumption"
      }
    ],
    "operations": [
      {
        "id": "OPS-001",
        "decision": "Instrument load outcome, duration, row count, retry, stale-response suppression, and a privacy-safe correlation ID through an approved organizational sink.",
        "rationale": "These signals support failure diagnosis without collecting Account or user payloads.",
        "evidence_status": "Assumption"
      },
      {
        "id": "OPS-002",
        "decision": "Treat telemetry failure as non-blocking and surface only actionable, sanitized user feedback for data-load failures.",
        "rationale": "Observability must not prevent the account review journey or leak internal response details.",
        "evidence_status": "Confirmed"
      }
    ],
    "alm": [
      {
        "id": "ALM-001",
        "decision": "Package the web resource and app-navigation change in the existing approved solution using the organization-selected publisher, with explicit app and table dependencies.",
        "rationale": "A single solution-owned slice supports deterministic promotion and rollback.",
        "evidence_status": "Assumption"
      },
      {
        "id": "ALM-002",
        "decision": "Promote only after static checks, automated tests, solution validation, dependency inspection, and authorized test-environment smoke evidence pass.",
        "rationale": "Local and package evidence must remain distinct from deployment and runtime proof.",
        "evidence_status": "Confirmed"
      }
    ]
  },
