  "acceptance_criteria": [
    {
      "id": "AC-001",
      "given": "An authorized reviewer opens Account Review and the synthetic dataset contains more than ten active accounts with distinct createdon values",
      "when": "The initial load completes",
      "then": "Exactly ten rows are shown in descending createdon order using the service-returned order",
      "evidence": "Automated data-module test plus authorized runtime capture using a known synthetic fixture"
    },
    {
      "id": "AC-002",
      "given": "The Account Review surface initiates a load",
      "when": "The data module requests accounts",
      "then": "It uses exactly Xrm.WebApi.retrieveMultipleRecords(\"account\", \"?$select=name,accountnumber&$filter=statecode eq 0&$orderby=createdon desc&$top=10\")",
      "evidence": "Source assertion and mocked Xrm.WebApi contract test"
    },
    {
      "id": "AC-003",
      "given": "Active and inactive synthetic accounts exist",
      "when": "Account Review loads",
      "then": "Only active accounts are displayed and each row exposes only name and accountnumber",
      "evidence": "Synthetic functional test with mixed statecode values and rendered-column assertion"
    },
    {
      "id": "AC-004",
      "given": "No active accounts are returned",
      "when": "The request succeeds",
      "then": "The loading state ends and an accessible no-active-accounts message is displayed without an empty grid ambiguity",
      "evidence": "Automated empty-state UI test and runtime smoke evidence"
    },
    {
      "id": "AC-005",
      "given": "The reviewer lacks Account read permission",
      "when": "The request is denied",
      "then": "No account data or internal response details are rendered and a permission-safe message is announced",
      "evidence": "Authorized negative-role runtime test and security review"
    },
    {
      "id": "AC-006",
      "given": "A transient request failure occurs",
      "when": "The error is returned",
      "then": "A sanitized retryable error is shown, keyboard focus remains predictable, and one user retry starts one new request",
      "evidence": "Mocked failure-and-retry test plus accessibility assertion"
    },
    {
      "id": "AC-007",
      "given": "A slower earlier request completes after a newer refresh request",
      "when": "Both responses arrive",
      "then": "Only the newer response can update the visible grid and telemetry records stale-response suppression",
      "evidence": "Deterministic out-of-order response test"
    },
    {
      "id": "AC-008",
      "given": "The review succeeds or fails",
      "when": "Telemetry is emitted",
      "then": "It includes correlation ID, outcome, duration, row count, retry, and stale-response indicators but excludes account, user, credential, URL, and response payload data",
      "evidence": "Telemetry schema test and captured sanitized event inspection"
    },
    {
      "id": "AC-009",
      "given": "The page is used with keyboard navigation, screen-reader announcements, long values, or a narrow viewport",
      "when": "The user reviews or retries the load",
      "then": "Controls remain operable, status changes are announced, focus is visible, and content remains readable without hiding accessible values",
      "evidence": "Automated accessibility checks and manual keyboard, screen-reader, long-content, and narrow-layout review"
    }
  ],
  "negative_paths": [
    {
      "id": "NP-001",
      "condition": "Dataverse returns an authorization failure.",
      "expected_behavior": "Render no account values, show a sanitized permission message, emit a payload-free denied outcome, and do not retry automatically.",
      "evidence": "Negative-role runtime test"
    },
    {
      "id": "NP-002",
      "condition": "Dataverse returns a transient network, throttling, or service failure.",
      "expected_behavior": "End loading, show a sanitized retry action, prevent retry storms, and correlate the failure without recording the response body.",
      "evidence": "Mocked transient-failure and repeated-retry tests"
    },
    {
      "id": "NP-003",
      "condition": "The response is missing the entities array or has an unexpected shape.",
      "expected_behavior": "Fail closed, render no partial rows, show a generic retryable error, and emit an invalid-response outcome.",
      "evidence": "Malformed-response unit tests"
    },
    {
      "id": "NP-004",
      "condition": "The user activates refresh repeatedly while a request is active.",
      "expected_behavior": "Only one active refresh is accepted, the control remains disabled until completion, and duplicate rendering is prevented.",
      "evidence": "Rapid-activation reliability test"
    },
    {
      "id": "NP-005",
      "condition": "An older request completes after a newer request.",
      "expected_behavior": "The older response is ignored and cannot overwrite the latest visible state.",
      "evidence": "Out-of-order promise-resolution test"
    },
    {
      "id": "NP-006",
      "condition": "More than ten active accounts exist.",
      "expected_behavior": "The surface displays no more than the ten rows returned by the validated server-side top query and does not fetch a second page.",
      "evidence": "Synthetic dataset test with more than ten active accounts"
    },
    {
      "id": "NP-007",
      "condition": "Two accounts share the same createdon value.",
      "expected_behavior": "The service-defined relative order is preserved and no unapproved client-side secondary ordering is introduced.",
      "evidence": "Tie-case contract test and documented product limitation"
    },
    {
      "id": "NP-008",
      "condition": "The telemetry destination is unavailable.",
      "expected_behavior": "The review experience continues, no account payload is buffered locally, and telemetry failure does not replace the data-load outcome shown to the user.",
      "evidence": "Telemetry-failure resilience test"
    }
  ],
  "tests": [
    {
      "id": "TEST-001",
      "class": "functional",
      "scope": "Exact Xrm.WebApi method, table name, query string, and single-call behavior",
      "expected": "The data module issues the validated contract unchanged and makes no broader retrieval.",
      "evidence_required": "Passing mocked Xrm.WebApi unit test",
      "status": "planned"
    },
    {
      "id": "TEST-002",
      "class": "functional",
      "scope": "Active filtering, top-ten limit, service ordering, projected columns, null handling, and empty state",
