      "evidence_required": "Passing deterministic concurrency and failure-injection tests",
      "status": "planned"
    },
    {
      "id": "TEST-005",
      "class": "accessibility",
      "scope": "Keyboard operation, visible focus, loading and error announcements, grid semantics, long content, zoom, and narrow viewport",
