      "evidence_required": "Solution validation output, dependency report, and reviewed source/package diff",
      "status": "planned"
    },
    {
      "id": "TEST-008",
      "class": "deployment",
      "scope": "Authorized test import, app-navigation readback, security-role verification, telemetry binding, and runtime smoke paths",
      "expected": "The deployed target configuration matches the approved package and success, empty, permission, and retry paths work in the target.",
      "evidence_required": "Import record, configuration readback, and timestamped sanitized runtime evidence",
      "status": "not-run"
    },
    {
      "id": "TEST-009",
      "class": "rollback",
      "scope": "Removal or disabling of the navigation entry and restoration of the prior solution version",
      "expected": "The slice can be withdrawn without Account data repair or residual app navigation.",
      "evidence_required": "Rehearsed rollback record in a non-production environment",
      "status": "not-run"
    }
  ],
